#!/usr/bin/env python3
"""
Early-ADMET card for a single screening hit, from SMILES alone.

Three layers, each independently traceable:
  1. Physicochemical descriptors (RDKit)
  2. Rule-based druglikeness flags + structural alerts (RDKit rule implementations + FilterCatalog)
  3. Measured/read-across ADMET endpoints (ChEMBL REST API) -- requires network + manual curation

Usage:
    pip install rdkit requests
    python early_admet.py "CC(=O)Oc1ccccc1C(=O)O" --name aspirin
"""
import argparse
import json
import sys

from rdkit import Chem
from rdkit.Chem import Crippen, Descriptors, Lipinski, QED, rdMolDescriptors
from rdkit.Chem.FilterCatalog import FilterCatalog, FilterCatalogParams

try:
    import requests
except ImportError:
    requests = None


# ---------- Layer 1: physicochemical descriptors ----------

def compute_descriptors(mol):
    return {
        "molecular_weight": round(Descriptors.MolWt(mol), 2),
        "clogp_crippen": round(Crippen.MolLogP(mol), 2),
        "tpsa": round(rdMolDescriptors.CalcTPSA(mol), 2),
        "hbd": Lipinski.NumHDonors(mol),
        "hba": Lipinski.NumHAcceptors(mol),
        "rotatable_bonds": rdMolDescriptors.CalcNumRotatableBonds(mol),
        "ring_count": rdMolDescriptors.CalcNumRings(mol),
        "aromatic_rings": rdMolDescriptors.CalcNumAromaticRings(mol),
        "fraction_csp3": round(rdMolDescriptors.CalcFractionCSP3(mol), 2),
        "molar_refractivity": round(Crippen.MolMR(mol), 2),
        "qed": round(QED.qed(mol), 3),
    }


# ---------- Layer 2: rule-based flags ----------

def lipinski_ro5(d):
    violations = []
    if d["molecular_weight"] > 500:
        violations.append(f"MW {d['molecular_weight']} > 500")
    if d["clogp_crippen"] > 5:
        violations.append(f"cLogP {d['clogp_crippen']} > 5")
    if d["hbd"] > 5:
        violations.append(f"HBD {d['hbd']} > 5")
    if d["hba"] > 10:
        violations.append(f"HBA {d['hba']} > 10")
    return {"rule": "Lipinski Ro5", "pass": len(violations) <= 1, "violations": violations}


def veber(d):
    violations = []
    if d["rotatable_bonds"] > 10:
        violations.append(f"RotB {d['rotatable_bonds']} > 10")
    if d["tpsa"] > 140:
        violations.append(f"TPSA {d['tpsa']} > 140")
    return {"rule": "Veber", "pass": len(violations) == 0, "violations": violations}


def egan(d):
    # BOILED-Egg / Egan 'egg-white' region: good passive GI absorption
    in_egg = (-1.0 <= d["clogp_crippen"] <= 5.88) and (d["tpsa"] <= 131.6)
    return {"rule": "Egan (WLOGP/TPSA egg)", "pass": in_egg,
            "violations": [] if in_egg else [f"logP={d['clogp_crippen']}, TPSA={d['tpsa']} outside egg-white bounds"]}


def muegge(d, mol):
    violations = []
    if not (200 <= d["molecular_weight"] <= 600):
        violations.append(f"MW {d['molecular_weight']} outside [200,600]")
    if not (-2 <= d["clogp_crippen"] <= 5):
        violations.append(f"cLogP {d['clogp_crippen']} outside [-2,5]")
    if d["tpsa"] > 150:
        violations.append(f"TPSA {d['tpsa']} > 150")
    if d["ring_count"] > 7:
        violations.append(f"rings {d['ring_count']} > 7")
    if rdMolDescriptors.CalcNumHeteroatoms(mol) <= 1:
        violations.append("heteroatom count <= 1")
    if mol.GetNumAtoms() <= 4:  # crude carbon-count proxy
        violations.append("too few heavy atoms")
    if d["hba"] > 10:
        violations.append(f"HBA {d['hba']} > 10")
    if d["hbd"] > 5:
        violations.append(f"HBD {d['hbd']} > 5")
    if d["rotatable_bonds"] > 15:
        violations.append(f"RotB {d['rotatable_bonds']} > 15")
    return {"rule": "Muegge", "pass": len(violations) == 0, "violations": violations}


def structural_alerts(mol):
    out = {}
    for name, catalog_flag in [("PAINS", FilterCatalogParams.FilterCatalogs.PAINS),
                                ("BRENK", FilterCatalogParams.FilterCatalogs.BRENK)]:
        params = FilterCatalogParams()
        params.AddCatalog(catalog_flag)
        catalog = FilterCatalog(params)
        matches = catalog.GetMatches(mol)
        out[name] = [m.GetDescription() for m in matches]
    return out


# ---------- Layer 3: ChEMBL read-across (network, manual judgment required) ----------

CHEMBL_BASE = "https://www.ebi.ac.uk/chembl/api/data"

def chembl_lookup(smiles):
    """Best-effort exact/similarity match against ChEMBL. Returns raw records for manual curation --
    this layer is NOT fully automatable: a human must judge assay relevance and read-across distance."""
    if requests is None:
        return {"error": "requests not installed; run `pip install requests` to enable this layer"}
    try:
        resp = requests.get(f"{CHEMBL_BASE}/molecule.json",
                             params={"molecule_structures__canonical_smiles__flexmatch": smiles},
                             timeout=15)
        resp.raise_for_status()
        molecules = resp.json().get("molecules", [])
        if not molecules:
            return {"note": "no exact ChEMBL match; consider a similarity search "
                             f"({CHEMBL_BASE}/similarity/<smiles>/70.json) for analog read-across"}
        chembl_id = molecules[0]["molecule_chembl_id"]
        act_resp = requests.get(f"{CHEMBL_BASE}/activity.json",
                                 params={"molecule_chembl_id": chembl_id, "limit": 1000}, timeout=15)
        act_resp.raise_for_status()
        activities = act_resp.json().get("activities", [])
        return {"chembl_id": chembl_id, "n_activities": len(activities), "activities": activities}
    except Exception as e:
        return {"error": str(e)}


# ---------- report assembly ----------

def build_report(smiles, name=None):
    mol = Chem.MolFromSmiles(smiles)
    if mol is None:
        raise ValueError(f"Could not parse SMILES: {smiles}")

    d = compute_descriptors(mol)
    flags = [lipinski_ro5(d), veber(d), egan(d), muegge(d, mol)]
    alerts = structural_alerts(mol)
    chembl = chembl_lookup(smiles)

    report = {
        "compound": name or smiles,
        "smiles": smiles,
        "layer_1_physicochemical": d,
        "layer_2_rule_flags": flags,
        "layer_2_structural_alerts": alerts,
        "layer_3_chembl_raw": chembl,
        "caveat": ("This is a hypothesis, not a measurement. Layer 3 requires a human to judge "
                   "assay relevance, exact-match vs. analog read-across, and units before citing "
                   "any value in a decision document."),
    }
    return report


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("smiles")
    ap.add_argument("--name", default=None)
    ap.add_argument("--json-out", default=None)
    args = ap.parse_args()

    report = build_report(args.smiles, args.name)
    text = json.dumps(report, indent=2, default=str)
    if args.json_out:
        with open(args.json_out, "w") as f:
            f.write(text)
    print(text)

